package com.sourcetoolkit.app;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.provider.DocumentsContract;
import android.view.*;
import android.widget.*;
import androidx.documentfile.provider.DocumentFile;
import java.io.*;
import java.util.*;

public class MainActivity extends Activity {
    private static final int PICK_GAME = 1001, PICK_IMPORT = 1002, PICK_FILE = 1003;
    private Uri gameUri;
    private LinearLayout root, body;
    private boolean dark = true;
    private String currentMod = "";
    private int bg, panel, fg, muted, accent;

    @Override public void onCreate(Bundle b) { super.onCreate(b); String saved=getPreferences(0).getString("game_uri", ""); if(!saved.isEmpty()) gameUri=Uri.parse(saved); renderHome(); }

    private void colors(){ bg=dark?0xFF17191D:0xFFE5EAF0; panel=dark?0xFF252A31:0xFFF4F6F9; fg=dark?0xFFE8EDF2:0xFF202833; muted=dark?0xFF9AA6B2:0xFF65717E; accent=dark?0xFF8FAFCB:0xFF486E91; }
    private GradientDrawable shape(int color,int radius){ GradientDrawable d=new GradientDrawable(); d.setColor(color); d.setCornerRadius(radius); return d; }
    private TextView text(String s,int size,boolean bold){ TextView t=new TextView(this); t.setText(s); t.setTextSize(size); t.setTextColor(fg); if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD); t.setGravity(Gravity.CENTER_VERTICAL); return t; }
    private void base(String title,String subtitle){ colors(); root=new LinearLayout(this); root.setOrientation(1); root.setPadding(18,12,18,18); root.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{dark?0xFF20242A:0xFFD1DAE4,bg,dark?0xFF101215:0xFFE9EDF2})); setContentView(root);
        LinearLayout top=new LinearLayout(this); top.setGravity(Gravity.CENTER_VERTICAL); TextView back=text("‹",32,true); back.setPadding(0,0,18,0); back.setOnClickListener(v->renderHome()); top.addView(back); LinearLayout titles=new LinearLayout(this); titles.setOrientation(1); titles.addView(text(title,21,true)); TextView sub=text(subtitle,12,false); sub.setTextColor(muted); titles.addView(sub); top.addView(titles,new LinearLayout.LayoutParams(0,-2,1)); TextView theme=text(dark?"☾":"☀",22,true); theme.setOnClickListener(v->{dark=!dark;renderHome();}); top.addView(theme); root.addView(top); View line=new View(this); line.setBackgroundColor(dark?0x334FFFFF:0x33505D6A); LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,1); lp.topMargin=14;lp.bottomMargin=14;root.addView(line,lp);
        ScrollView sc=new ScrollView(this); body=new LinearLayout(this); body.setOrientation(1); sc.addView(body); root.addView(sc,new LinearLayout.LayoutParams(-1,0,1)); }
    private void card(String title,String desc,Runnable action){ LinearLayout c=new LinearLayout(this); c.setOrientation(1); c.setPadding(16,13,16,13); c.setBackground(shape(panel,18)); c.setClickable(true); c.setOnClickListener(v->action.run()); TextView a=text(title,17,true); c.addView(a); TextView b=text(desc,12,false); b.setTextColor(muted); LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=10;body.addView(c,p);c.addView(b); }
    private void button(String label,Runnable action){ TextView b=text(label,15,true); b.setGravity(Gravity.CENTER); b.setPadding(14,13,14,13); b.setBackground(shape(dark?0xFF303943:0xFFD3DEE8,14)); b.setOnClickListener(v->action.run()); LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=9;body.addView(b,p); }
    private void note(String s){ TextView t=text(s,12,false); t.setTextColor(muted); t.setPadding(4,8,4,12); body.addView(t); }
    private DocumentFile game(){return gameUri==null?null:DocumentFile.fromTreeUri(this,gameUri);}
    private DocumentFile folder(DocumentFile parent,String name){ DocumentFile f=parent.findFile(name); return f!=null&&f.isDirectory()?f:parent.createDirectory(name); }
    private void pickGame(){ Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE); i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION); startActivityForResult(i,PICK_GAME); }
    @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(res!=RESULT_OK||data==null)return; Uri u=data.getData(); if(req==PICK_GAME){gameUri=u;getContentResolver().takePersistableUriPermission(u,data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));getPreferences(0).edit().putString("game_uri",u.toString()).apply();renderHome();}else if(req==PICK_IMPORT){DocumentFile src=DocumentFile.fromTreeUri(this,u); DocumentFile g=game(); if(src!=null&&g!=null){DocumentFile addons=folder(g,"addons");copyTree(src,addons,src.getName());renderMods();}}else if(req==PICK_FILE){openPickedFile(u);} }
    private void renderHome(){base("SOURCE TOOLKIT","Source Engine · GMod utilities"); note(gameUri==null?"游戏目录：尚未选择":"已绑定游戏目录："+(game()==null?"":game().getName())); button(gameUri==null?"选择游戏目录":"更改游戏目录",()->pickGame()); card("Gmod Mod","管理、创建、导入和编辑 Garry's Mod 模组",()->renderMods()); card("VTF 转换","将 PNG / JPG 图片转换为 VTF（转换器模块待接入）",()->renderVtf()); card("VPK 浏览器","读取 VPK 文件目录并导出资源",()->renderVpk()); card("设置与工作区","目录授权、主题与项目存放位置",()->renderSettings()); }
    private void requireGame(Runnable r){if(game()==null){new AlertDialog.Builder(this).setMessage("请先选择游戏目录（包含 addons 文件夹的 Garry's Mod 目录）。").setPositiveButton("选择目录",(d,w)->pickGame()).setNegativeButton("取消",null).show();}else r.run();}
    private void renderMods(){requireGame(()->{base("Gmod Mod","MOD WORKSPACE");DocumentFile g=game(); DocumentFile addons=folder(g,"addons"); DocumentFile disabled=folder(g,"addons_disabled"); note("游戏目录 / "+g.getName()+" / addons");button("管理 Mod",()->showModList(addons,disabled));button("添加 Mod · 新建项目",()->createMod(addons));button("添加 Mod · 导入文件夹",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(67);startActivityForResult(i,PICK_IMPORT);});button("编辑 Mod / 浏览文件",()->showModList(addons,disabled));note("禁用操作会将模组目录移动到同级 addons_disabled；重新启用会移回 addons。" );});}
    private void showModList(DocumentFile addons,DocumentFile disabled){base("管理 Mod","ADDONS");button("刷新列表",()->showModList(addons,disabled));note("已启用");int n=0;for(DocumentFile f:addons.listFiles())if(f.isDirectory()||f.getName()!=null&&f.getName().endsWith(".gma")){addModRow(f,addons,disabled,true);n++;}if(n==0)note("暂无已启用模组");note("已禁用");for(DocumentFile f:disabled.listFiles())if(f.isDirectory()||f.getName()!=null&&f.getName().endsWith(".gma"))addModRow(f,addons,disabled,false);}
    private void addModRow(DocumentFile f,DocumentFile addons,DocumentFile disabled,boolean enabled){LinearLayout row=new LinearLayout(this);row.setPadding(12,10,12,10);row.setGravity(Gravity.CENTER_VERTICAL);row.setBackground(shape(panel,12));TextView name=text(f.getName(),14,true);row.addView(name,new LinearLayout.LayoutParams(0,-2,1));TextView act=text(enabled?"禁用":"启用",13,true);act.setTextColor(accent);act.setPadding(10,8,10,8);act.setOnClickListener(v->{DocumentFile dest=enabled?disabled:addons;try{DocumentsContract.moveDocument(getContentResolver(),f.getUri(),(enabled?addons:disabled).getUri(),dest.getUri());showModList(addons,disabled);}catch(Exception e){toast("移动失败："+e.getMessage());}});row.addView(act);TextView edit=text("打开",13,true);edit.setPadding(10,8,0,8);edit.setOnClickListener(v->{currentMod=f.getName();browse(f);});row.addView(edit);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=7;body.addView(row,p);}
    private void createMod(DocumentFile addons){EditText input=new EditText(this);input.setSingleLine(true);input.setHint("例如 my_first_addon");new AlertDialog.Builder(this).setTitle("新建 Mod 项目").setView(input).setPositiveButton("创建",(d,w)->{String name=input.getText().toString().trim();if(name.isEmpty())return;DocumentFile mod=addons.createDirectory(name);if(mod==null){toast("创建失败");return;}folder(mod,"lua");folder(mod,"materials");folder(mod,"models");folder(mod,"sound");write(mod,"README.txt","Garry's Mod addon project\n");currentMod=name;browse(mod);}).setNegativeButton("取消",null).show();}
    private void browse(DocumentFile dir){base(dir.getName(),"MOD FILE EXPLORER");button("新建文件",()->newFile(dir,false));button("新建文件夹",()->newFile(dir,true));button("导入文件",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,PICK_FILE);});for(DocumentFile f:dir.listFiles()){TextView item=text((f.isDirectory()?"▸  ":"   ")+f.getName(),14,true);item.setPadding(12,12,8,12);item.setBackground(shape(panel,10));item.setOnClickListener(v->{if(f.isDirectory())browse(f);else if(f.getName()!=null&&f.getName().toLowerCase().endsWith(".lua"))editText(f);else if(f.getName()!=null&&f.getName().toLowerCase().endsWith(".vtf"))toast("VTF 预览器将在资源模块中提供");else if(isAudio(f.getName()))playAudio(f);else toast("文件："+f.getName());});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=6;body.addView(item,p);}}
    private void newFile(DocumentFile dir,boolean isDir){EditText e=new EditText(this);e.setHint(isDir?"文件夹名称":"文件名（如 init.lua）");new AlertDialog.Builder(this).setTitle(isDir?"新建文件夹":"新建文件").setView(e).setPositiveButton("创建",(d,w)->{String n=e.getText().toString().trim();if(n.isEmpty())return;if(isDir)dir.createDirectory(n);else write(dir,n,"");browse(dir);}).setNegativeButton("取消",null).show();}
    private void editText(DocumentFile f){try{InputStream in=getContentResolver().openInputStream(f.getUri());ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);in.close();EditText e=new EditText(this);e.setText(out.toString("UTF-8"));e.setGravity(Gravity.TOP|Gravity.LEFT);e.setTypeface(Typeface.MONOSPACE);e.setTextSize(13);new AlertDialog.Builder(this).setTitle(f.getName()).setView(e).setPositiveButton("保存",(d,w)->{try{OutputStream o=getContentResolver().openOutputStream(f.getUri(),"wt");o.write(e.getText().toString().getBytes("UTF-8"));o.close();toast("已保存");}catch(Exception ex){toast("保存失败");}}).setNegativeButton("取消",null).show();}catch(Exception ex){toast("无法读取文件");}}
    private void renderVtf(){base("VTF 转换","IMAGE → VALVE TEXTURE FORMAT");note("选择一张或多张 PNG / JPG 图片。多张图片可分别设置帧时长；单张图片不显示帧时长选项。");button("选择图片",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,PICK_FILE);});note("当前版本提供界面与文件授权基础；VTF 编码器尚未接入，暂不会生成伪造的 .vtf 文件。后续将实现 DXT1 / DXT5 / RGBA8888 与动画帧写入。" );}
    private void renderVpk(){base("VPK 浏览器","VALVE PACK FILE");button("选择 VPK 文件",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,PICK_FILE);});note("计划支持 VPK v1 / v2 目录索引、分块归档读取、单文件导出与全部解压。当前版本尚未接入解析器。" );}
    private void renderSettings(){base("设置与工作区","PREFERENCES");button("选择 / 更改游戏目录",()->pickGame());button("切换深色 / 浅色主题",()->{dark=!dark;renderSettings();});note("语言跟随 Android 系统语言。Android 8.0（API 26）为最低兼容目标。\n当前游戏目录："+(game()==null?"未设置":game().getUri().toString()));}
    private void openPickedFile(Uri u){String type=getContentResolver().getType(u);if(type!=null&&type.startsWith("audio/")){try{android.media.MediaPlayer mp=new android.media.MediaPlayer();mp.setDataSource(this,u);mp.prepare();mp.start();toast("正在播放音频");}catch(Exception e){toast("无法播放音频");}}else toast("已选择："+u.getLastPathSegment()+"（此操作入口将在导入/转换器完成后接入）");}
    private boolean isAudio(String n){if(n==null)return false;n=n.toLowerCase();return n.endsWith(".wav")||n.endsWith(".mp3")||n.endsWith(".ogg")||n.endsWith(".mp2")||n.endsWith(".flac");}
    private void playAudio(DocumentFile f){try{android.media.MediaPlayer mp=new android.media.MediaPlayer();mp.setDataSource(this,f.getUri());mp.prepare();mp.start();toast("正在播放音频");}catch(Exception e){toast("无法播放音频");}}
    private void write(DocumentFile dir,String name,String data){try{DocumentFile f=dir.createFile("text/plain",name);if(f!=null){OutputStream o=getContentResolver().openOutputStream(f.getUri());o.write(data.getBytes("UTF-8"));o.close();}}catch(Exception e){toast("写入失败");}}
    private void copyTree(DocumentFile src,DocumentFile dst,String name){try{if(src.isDirectory()){DocumentFile d=dst.createDirectory(name);for(DocumentFile c:src.listFiles())copyTree(c,d,c.getName());}else{DocumentFile d=dst.createFile(getContentResolver().getType(src.getUri()),name);InputStream in=getContentResolver().openInputStream(src.getUri());OutputStream out=getContentResolver().openOutputStream(d.getUri());byte[] b=new byte[16384];int n;while((n=in.read(b))>0)out.write(b,0,n);in.close();out.close();}}catch(Exception e){toast("导入失败："+e.getMessage());}}
    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
}
